import React, { useEffect, useState } from "react";
import liff from "@line/liff";
import { Card, Input, Button, Alert, Form, Typography, Avatar } from "antd";
import { IdcardOutlined } from "@ant-design/icons";
import axios from "axios";

const { Title, Text } = Typography;

function App() {
  const [profile, setProfile] = useState(null);
  const [citizenId, setCitizenId] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // โหลด LIFF
  useEffect(() => {
    const initLiff = async () => {
      try {
        await liff.init({ liffId: "2008683576-hqMNc47B" });

        if (!liff.isLoggedIn()) {
          liff.login();
          return;
        }

        await liff.ready;

        const profile = await liff.getProfile();
        // const idToken = liff.getDecodedIDToken();

        // setProfile({
        //   userId: idToken.sub,
        //   displayName: idToken.name,
        //   pictureUrl: idToken.picture,
        // });

        setProfile(profile);

        console.log("LIFF Profile:", profile);
      } catch (error) {
        console.error("LIFF init error", error);
      }
    };

    initLiff();
  }, []);
  // ตรวจเลขบัตรประชาชน
  const validateCitizenId = (id) => {
    if (!/^[0-9]{13}$/.test(id)) return false;
    let sum = 0;
    for (let i = 0; i < 12; i++) sum += parseInt(id[i]) * (13 - i);
    let check = (11 - (sum % 11)) % 10;
    return check === Number(id[12]);
  };

  const handleSubmit = async () => {
    if (!validateCitizenId(citizenId)) {
      setError("เลขบัตรประชาชนไม่ถูกต้อง");
      return;
    }

    setError("");
    setLoading(true);
    const body = {
      citizenId,
      lineUserId: profile?.userId,
      displayName: profile?.displayName,
    };

    // console.log("Profile", profile);
    // console.log("Body", body);

    // ส่งไป backend

    await axios
      .post("https://shark-app-j9jc9.ondigitalocean.app/register/line-oa", body)
      // .post("http://localhost:8080/register/line-oa", body)
      .then((res) => {
        console.log(res);
        if (res.status === 201) {
          alert(`ลงทะเบียนสำเร็จ!`);
        } else {
          alert(
            `ผู้ใช้ไลน์นี้ได้ลงทะเบียนแล้ว ด้วยหมายเลข ${res?.data?.data?.citizenId} \r\nหากไม่ถูกต้องกรุณาติดต่อเจ้าหน้าที่`
          );
        }
      })
      .catch((err) => {
        alert(err);
      })
      .finally(() => {
        setLoading(false);
        liff.closeWindow();
      });
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg,#E0EAFC,#CFDEF3)",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        padding: 20,
      }}
    >
      <Card
        bordered={false}
        style={{
          width: "100%",
          maxWidth: 420,
          borderRadius: 20,
          padding: "20px 25px",
          boxShadow: "0 10px 30px rgba(0,0,0,0.15)",
          textAlign: "center",
        }}
      >
        <Title level={3} style={{ marginBottom: 10 }}>
          ลงทะเบียนเพื่อผูกบัญชี
        </Title>

        {profile && (
          <div style={{ marginBottom: 20 }}>
            <Avatar
              src={profile.pictureUrl}
              size={80}
              style={{ marginBottom: 8 }}
            />
            <Text strong style={{ display: "block", fontSize: 18 }}>
              {profile.displayName}
            </Text>
          </div>
        )}

        {/* Error Message */}
        {error && (
          <Alert
            message={error}
            type="error"
            showIcon
            style={{ marginBottom: 15 }}
          />
        )}

        <Form layout="vertical">
          <Form.Item label="เลขบัตรประชาชน 13 หลัก" required>
            <Input
              size="large"
              placeholder="กรอกเลขบัตรประชาชน"
              maxLength={13}
              prefix={<IdcardOutlined />}
              value={citizenId}
              onChange={(e) => setCitizenId(e.target.value)}
              style={{ borderRadius: 10 }}
            />
          </Form.Item>

          <Button
            type="primary"
            size="large"
            block
            loading={loading}
            onClick={handleSubmit}
            style={{
              borderRadius: 12,
              height: 48,
              background: "linear-gradient(135deg,#3F51B5,#1A237E)",
            }}
          >
            ยืนยันข้อมูล
          </Button>
        </Form>
      </Card>
    </div>
  );
}

export default App;
